        <pre className="max-h-[450px] overflow-auto whitespace-pre-wrap break-words border-t border-white/10 bg-black/50 p-4 text-[10px] leading-5 text-gray-500">
          {JSON.stringify(nuclei, null, 2)}
        </pre>
