// ==================================================
// ADMIN AUDIT TRAIL
// ==================================================
function AuditTrail({ menu = 'admin-user-activity' }) {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");
  const [moduleFilter, setModuleFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("ALL");

  const auditViews = {
    "admin-user-activity": {
      title: "User Activity",
      description: "Review recorded user-related activity.",
      keywords: ["user registered", "user created", "user updated", "user deleted", "client assignment", "user client assignment updated"],
    },
    "admin-admin-activity": {
      title: "Admin Activity",
      description: "Review recorded administrative actions.",
      keywords: ["admin action", "administrator action", "admin activity", "user created", "client assignment", "user client assignment updated", "role change", "permission change", "user tool permissions updated", "configuration change"],
    },
    "admin-login-history": {
      title: "Login History",
      description: "Review recorded login and authentication events.",
      keywords: ["login", "log in", "logout", "log out", "authentication", "sign in", "signin"],
    },
    "admin-permission-changes": {
      title: "Permission Changes",
      description: "Review recorded role and permission-related events.",
      keywords: ["permission", "role change", "role_update", "rbac", "privilege"],
    },
    "admin-configuration-changes": {
      title: "Configuration Changes",
      description: "Review recorded configuration and settings-related events.",
      keywords: ["configuration", "config", "settings"],
    },
    "admin-api-activity": {
      title: "API Activity",
      description: "Review recorded API and endpoint-related events.",
      keywords: ["api", "endpoint", "http request"],
    },
    "admin-audit-export": {
      title: "Audit Export",
      description: "Review audit events and export filtered records to CSV.",
      keywords: [],
    },
  };
  const auditView = auditViews[menu] || auditViews["admin-user-activity"];


  const loadLogs = async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      if (!token) {
        throw new Error("No authentication token found.");
      }

      const response = await axios.get(
        `${API_URL}/audit/logs?limit=500`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setLogs(Array.isArray(response.data) ? response.data : []);
    } catch (err) {
      console.error("Audit trail load error:", err);

      if (err.response?.data?.detail) {
        setError(err.response.data.detail);
      } else {
        setError("Unable to load audit trail.");
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadLogs();
  }, []);

  const modules = [
    "ALL",
    ...Array.from(
      new Set(
        logs
          .map((item) => item.module)
          .filter(Boolean)
      )
    ),
  ];

  const categoryLogs = auditView.keywords.length === 0
    ? logs
    : logs.filter((item) => {
        const searchableText = [
          item.action, item.module, item.details, item.username
        ].map((value) => String(value || "").toLowerCase()).join(" ");

        return auditView.keywords.some((keyword) =>
          searchableText.includes(keyword.toLowerCase())
        );
      });

  const filteredLogs = categoryLogs.filter((item) => {
    const query = search.toLowerCase().trim();

    const matchesSearch =
      !query ||
      String(item.username || "").toLowerCase().includes(query) ||
      String(item.action || "").toLowerCase().includes(query) ||
      String(item.module || "").toLowerCase().includes(query) ||
      String(item.ip_address || "").toLowerCase().includes(query) ||
      String(item.details || "").toLowerCase().includes(query);

    const matchesModule =
      moduleFilter === "ALL" ||
      String(item.module || "").toUpperCase() === moduleFilter.toUpperCase();

    const matchesStatus =
      statusFilter === "ALL" ||
      String(item.status || "").toUpperCase() === statusFilter.toUpperCase();

    return matchesSearch && matchesModule && matchesStatus;
  });

  const exportAuditCSV = () => {
    const columns = [
      ["ID", "id"],
      ["Timestamp", "created_at"],
      ["User ID", "user_id"],
      ["Username", "username"],
      ["Action", "action"],
      ["Module", "module"],
      ["IP Address", "ip_address"],
      ["Status", "status"],
      ["Details", "details"],
    ];

    const escapeCSV = (value) => {
      let text = String(value ?? "");
      // Prevent spreadsheet formula injection in exported text.
      if (/^[=+@\\-\\t\\r]/.test(text)) text = "'" + text;
      return '"' + text.replace(/"/g, '""') + '"';
    };

    const csv = [
      columns.map(([label]) => escapeCSV(label)).join(","),
      ...filteredLogs.map((item) =>
        columns.map(([, key]) => escapeCSV(item[key])).join(",")
      ),
    ].join("\r\n");

    const blob = new Blob(["\uFEFF", csv], {
      type: "text/csv;charset=utf-8;",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `SOC-Audit-Trail-${Date.now()}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  };

  const totalEvents = categoryLogs.length;
  const successfulEvents = categoryLogs.filter(
    (item) => String(item.status || "").toUpperCase() === "SUCCESS"
  ).length;
  const failedEvents = categoryLogs.filter(
    (item) => String(item.status || "").toUpperCase() === "FAILED"
  ).length;

  const todayKey = new Date().toDateString();
  const todayEvents = categoryLogs.filter((item) => {
    if (!item.created_at) return false;
    return new Date(item.created_at).toDateString() === todayKey;
  }).length;

  return (
    <div>
      <div className="flex flex-col justify-between gap-5 md:flex-row md:items-end">
        <div>
          <p className="text-xs uppercase tracking-[0.3em] text-red-500">
            Administration
          </p>

          <h1 className="mt-2 text-3xl font-bold">
            {auditView.title}
          </h1>

          <p className="mt-2 max-w-3xl text-sm leading-6 text-gray-500">
            {auditView.description}
          </p>
        </div>

        <button
          onClick={loadLogs}
          disabled={loading}
          className="border border-white/10 px-5 py-3 text-xs text-gray-400 transition hover:border-red-600 hover:text-white disabled:opacity-50"
        >
          {loading ? "Refreshing..." : "Refresh Audit Log"}
        </button>
      </div>

      {error && (
        <div className="mt-6 border border-red-600/30 bg-red-600/10 px-5 py-4 text-sm text-red-400">
          {error}
        </div>
      )}

      <div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <AdminStat
          title="Total Events"
          value={loading ? "—" : totalEvents}
          subtitle="Recorded audit events"
        />

        <AdminStat
          title="Successful"
          value={loading ? "—" : successfulEvents}
          subtitle="Successful operations"
        />

        <AdminStat
          title="Failed"
          value={loading ? "—" : failedEvents}
          subtitle="Failed operations"
        />

        <AdminStat
          title="Today"
          value={loading ? "—" : todayEvents}
          subtitle="Events recorded today"
        />
      </div>

      <div className="mt-6 grid gap-4 md:grid-cols-[1fr_220px_180px]">
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search user, action, module, IP..."
          className="w-full border border-white/10 bg-[#0d0d0d] px-4 py-3 text-sm text-white outline-none placeholder:text-gray-700 focus:border-red-600"
        />

        <select
          value={moduleFilter}
          onChange={(e) => setModuleFilter(e.target.value)}
          className="border border-white/10 bg-[#0d0d0d] px-4 py-3 text-sm text-gray-400 outline-none focus:border-red-600"
        >
          {modules.map((module) => (
            <option key={module} value={module}>
              {module === "ALL" ? "All Modules" : module}
            </option>
          ))}
        </select>

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className="border border-white/10 bg-[#0d0d0d] px-4 py-3 text-sm text-gray-400 outline-none focus:border-red-600"
        >
          <option value="ALL">All Status</option>
          <option value="SUCCESS">Success</option>
          <option value="FAILED">Failed</option>
        </select>
      </div>

      <div className="mt-6 overflow-hidden border border-white/10 bg-[#0d0d0d]">
        <div className="flex items-center justify-between border-b border-white/10 px-6 py-5">
          <div>
            <p className="text-sm font-semibold">
              Security Activity Log
            </p>

            <p className="mt-1 text-xs text-gray-600">
              Showing {filteredLogs.length} of {categoryLogs.length} events
            </p>
          </div>
          <button
            type="button"
            onClick={exportAuditCSV}
            disabled={loading || filteredLogs.length === 0}
            className="border border-white/10 px-4 py-2 text-xs text-gray-300 transition hover:border-red-600 hover:text-white disabled:cursor-not-allowed disabled:opacity-40"
          >
            Download CSV
          </button>
        </div>

        {loading ? (
          <div className="px-6 py-12 text-center text-sm text-gray-600">
            Loading audit events...
          </div>
        ) : filteredLogs.length === 0 ? (
          <div className="px-6 py-12 text-center text-sm text-gray-600">
            No audit events match the current filters.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1050px] text-left text-sm">
              <thead className="border-b border-white/10 bg-[#0a0a0a] text-[10px] uppercase tracking-wider text-gray-600">
                <tr>
                  <th className="px-5 py-4">Time</th>
                  <th className="px-5 py-4">User</th>
                  <th className="px-5 py-4">Action</th>
                  <th className="px-5 py-4">Module</th>
                  <th className="px-5 py-4">IP Address</th>
                  <th className="px-5 py-4">Status</th>
                  <th className="px-5 py-4">Details</th>
                </tr>
              </thead>

              <tbody className="divide-y divide-white/5">
                {filteredLogs.map((item) => {
                  const normalizedStatus = String(
                    item.status || ""
                  ).toUpperCase();

                  return (
                    <tr
                      key={item.id}
                      className="align-top transition hover:bg-white/[0.02]"
                    >
                      <td className="whitespace-nowrap px-5 py-5 text-xs text-gray-500">
                        {item.created_at
                          ? new Date(item.created_at).toLocaleString()
                          : "—"}
                      </td>

                      <td className="px-5 py-5">
                        <p className="text-sm font-semibold text-white">
                          {item.username || "Unknown"}
                        </p>
                        <p className="mt-1 text-[10px] text-gray-700">
                          User ID: {item.user_id ?? "—"}
                        </p>
                      </td>

                      <td className="px-5 py-5 text-sm text-gray-300">
                        {item.action || "—"}
                      </td>

                      <td className="px-5 py-5 text-xs text-gray-400">
                        {item.module || "—"}
                      </td>

                      <td className="px-5 py-5 font-mono text-xs text-gray-500">
                        {item.ip_address || "—"}
                      </td>

                      <td className="px-5 py-5">
                        <span
                          className={
                            normalizedStatus === "SUCCESS"
                              ? "text-xs font-semibold text-green-500"
                              : "text-xs font-semibold text-red-400"
                          }
                        >
                          {item.status || "—"}
                        </span>
                      </td>

                      <td className="max-w-[300px] px-5 py-5 text-xs leading-5 text-gray-500">
                        {item.details || "—"}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}


// ==================================================
// SERVER CONFIGURATION
// ==================================================
function ServerConfiguration() {
  const [configurations, setConfigurations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadConfigurations = async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      if (!token) {
        throw new Error("Your session has expired. Please login again.");
      }

      const response = await axios.get(
        `${API_URL}/client/server-configuration`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setConfigurations(
        Array.isArray(response.data?.configurations)
          ? response.data.configurations
          : []
      );
    } catch (err) {
      console.error("Server configuration error:", err);

      setError(
        err.response?.data?.detail ||
        err.message ||
        "Unable to load server configuration."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadConfigurations();

    const interval = setInterval(loadConfigurations, 15000);

    return () => clearInterval(interval);
  }, []);

  const onlineCount = configurations.filter(
    (configuration) =>
      ["online", "up", "alive"].includes(
        String(configuration.endpoint_status || "").toLowerCase()
      )
  ).length;

  const averageDiskUsage = configurations.length
    ? configurations.reduce(
        (total, configuration) =>
          total + Number(configuration.disk_usage_percent || 0),
        0
      ) / configurations.length
    : 0;

  const averageMemory = configurations.length
    ? configurations.reduce(
        (total, configuration) =>
          total + Number(configuration.memory_total_gb || 0),
        0
      ) / configurations.length
    : 0;

  const getStatusLabel = (status) => {
    const normalized = String(status || "").toLowerCase();

    if (["online", "up", "alive"].includes(normalized)) return "ONLINE";
    if (["offline", "down", "dead"].includes(normalized)) return "OFFLINE";
    return "UNKNOWN";
  };

  const getStatusClass = (status) => {
    const normalized = String(status || "").toLowerCase();

    if (["online", "up", "alive"].includes(normalized)) {
      return "text-green-500";
    }

    if (["offline", "down", "dead"].includes(normalized)) {
      return "text-red-500";
    }

    return "text-yellow-500";
  };

  return (
    <div>
      <div className="flex flex-col justify-between gap-5 md:flex-row md:items-end">
        <div>
          <p className="text-xs uppercase tracking-[0.3em] text-red-500">
            Server Security
          </p>

          <h1 className="mt-2 text-3xl font-bold">
            Server Configuration
          </h1>

          <p className="mt-2 max-w-3xl text-sm leading-6 text-gray-500">
            View persisted configuration and security-relevant properties
            reported directly by registered endpoints.
          </p>
        </div>

        <button
          onClick={loadConfigurations}
          disabled={loading}
          className="border border-white/10 px-5 py-3 text-xs text-gray-400 transition hover:border-red-600 hover:text-white disabled:opacity-50"
        >
          {loading ? "Refreshing..." : "Refresh Configuration"}
        </button>
      </div>

      {error && (
        <div className="mt-6 border border-red-600/30 bg-red-600/10 px-5 py-4 text-sm text-red-400">
          {error}
        </div>
      )}

      <div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <AdminStat
          title="Endpoints"
          value={loading ? "—" : configurations.length}
          subtitle="With configuration telemetry"
        />

        <AdminStat
          title="Online"
          value={loading ? "—" : onlineCount}
          subtitle="Current endpoint status"
          status
        />

        <AdminStat
          title="Avg Disk Usage"
          value={loading ? "—" : `${averageDiskUsage.toFixed(1)}%`}
          subtitle="Across reported endpoints"
        />

        <AdminStat
          title="Avg Memory"
          value={loading ? "—" : `${averageMemory.toFixed(2)} GB`}
          subtitle="Installed physical memory"
        />
      </div>

      <div className="mt-8 border border-white/10 bg-[#0d0d0d]">
        <div className="border-b border-white/10 px-6 py-5">
          <p className="text-sm font-semibold">
            Endpoint Server Configuration
          </p>

          <p className="mt-1 text-xs text-gray-600">
            Persisted configuration snapshots collected from registered
            endpoints. Automatically refreshed every 15 seconds.
          </p>
        </div>

        {loading && configurations.length === 0 ? (
          <div className="px-6 py-12 text-center text-sm text-gray-600">
            Loading server configuration...
          </div>
        ) : configurations.length === 0 ? (
          <div className="px-6 py-12 text-center">
            <p className="text-sm text-gray-400">
              No server configuration telemetry has been received yet.
            </p>
            <p className="mt-2 text-xs text-gray-600">
              Register an endpoint and run the Server Configuration collector
              to populate this view.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1500px] text-left">
              <thead>
                <tr className="border-b border-white/10 text-[10px] uppercase tracking-wider text-gray-600">
                  <th className="px-6 py-4">Endpoint</th>
                  <th className="px-6 py-4">Status</th>
                  <th className="px-6 py-4">Operating System</th>
                  <th className="px-6 py-4">Processor</th>
                  <th className="px-6 py-4">Memory</th>
                  <th className="px-6 py-4">Disk</th>
                  <th className="px-6 py-4">Uptime</th>
                  <th className="px-6 py-4">Environment</th>
                  <th className="px-6 py-4">Power Plan</th>
                  <th className="px-6 py-4">Last Seen</th>
                </tr>
              </thead>

              <tbody>
                {configurations.map((configuration) => (
                  <tr
                    key={configuration.id}
                    className="border-b border-white/5 transition hover:bg-white/[0.02]"
                  >
                    <td className="px-6 py-5">
                      <p className="text-sm font-medium text-gray-200">
                        {configuration.hostname || "Unknown"}
                      </p>

                      <p className="mt-1 text-xs text-gray-600 break-all">
                        {configuration.ip_address ||
                          configuration.endpoint_id ||
                          "No address recorded"}
                      </p>
                    </td>

                    <td className="px-6 py-5">
                      <span
                        className={`text-xs font-semibold ${getStatusClass(
                          configuration.endpoint_status
                        )}`}
                      >
                        {getStatusLabel(configuration.endpoint_status)}
                      </span>
                    </td>

                    <td className="px-6 py-5">
                      <p className="text-sm text-gray-300">
                        {configuration.os_name || "Unknown"}
                      </p>

                      <p className="mt-1 text-xs text-gray-600">
                        {configuration.os_version || "Version unknown"} ·{" "}
                        {configuration.architecture || "Architecture unknown"}
                      </p>
                    </td>

                    <td className="max-w-[260px] px-6 py-5">
                      <p className="text-sm text-gray-400">
                        {configuration.processor || "Unknown"}
                      </p>
                    </td>

                    <td className="px-6 py-5">
                      <p className="text-sm text-gray-300">
                        {configuration.memory_total_gb != null
                          ? `${Number(configuration.memory_total_gb).toFixed(2)} GB`
                          : "Unknown"}
                      </p>
                    </td>

                    <td className="px-6 py-5">
                      <p className="text-sm text-gray-300">
                        {configuration.disk_total_gb != null
                          ? `${Number(configuration.disk_total_gb).toFixed(2)} GB`
                          : "Unknown"}
                      </p>

                      <p className="mt-1 text-xs text-gray-600">
                        {configuration.disk_free_gb != null
                          ? `${Number(configuration.disk_free_gb).toFixed(2)} GB free`
                          : "Free space unknown"}
                        {" · "}
                        {configuration.disk_usage_percent != null
                          ? `${Number(configuration.disk_usage_percent).toFixed(1)}% used`
                          : "Usage unknown"}
                      </p>
                    </td>

                    <td className="px-6 py-5 text-sm text-gray-400">
                      {configuration.uptime || "Unknown"}
                    </td>

                    <td className="px-6 py-5">
                      <p className="text-sm text-gray-400">
                        {configuration.domain_or_workgroup || "Unknown"}
                      </p>

                      <p className="mt-1 text-xs text-gray-600">
                        {configuration.timezone || "Timezone unknown"}
                      </p>
                    </td>

                    <td className="max-w-[300px] px-6 py-5 text-xs text-gray-500">
                      {configuration.power_plan || "Unknown"}
                    </td>

                    <td className="px-6 py-5 text-xs text-gray-500">
                      {configuration.last_seen
                        ? new Date(`${configuration.last_seen}Z`).toLocaleString()
                        : "Unknown"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}



// ==================================================
// SECURITY COPILOT
